function req(sock, payload) {
  return new Promise((resolve, reject) => {
    const hex = payload.length.toString(16).padStart(4, '0');
    sock.write(hex + payload);
    let buf = Buffer.alloc(0);
    const timer = setTimeout(() => reject(new Error('timeout waiting for OKAY')), 10000);
    const onData = (chunk) => {
      buf = Buffer.concat([buf, chunk]);
      if (buf.length >= 4) {
        const head = buf.slice(0, 4).toString('ascii');
        if (head === 'OKAY' || head === 'FAIL') {
          clearTimeout(timer);
          sock.removeListener('data', onData);
          if (head === 'FAIL') {
            const len = parseInt(buf.slice(4, 8).toString('ascii'), 16);
            const err = buf.slice(8, 8 + len).toString('utf8');
            reject(new Error('FAIL: ' + err));
          } else {
            resolve(buf.slice(4));
          }
        }
      }
    };
    sock.on('data', onData);
  });
}
