const net = require('net');
const SERIAL = 'AVNS023705001888';
const PORT = 5037;

function hex4(s) { return s.length.toString(16).padStart(4, '0') + s; }

function hostQuery(payload) {
  return new Promise((resolve, reject) => {
    const sock = net.connect(PORT, '127.0.0.1');
    let buf = Buffer.alloc(0);
    const timer = setTimeout(() => { sock.destroy(); reject(new Error('timeout')); }, 60000);
    sock.on('connect', () => sock.write(hex4(payload)));
    sock.on('data', (c) => {
      buf = Buffer.concat([buf, c]);
      if (buf.length < 4) return;
      const head = buf.slice(0, 4).toString('ascii');
      if (head === 'OKAY') {
        if (buf.length < 8) return;
        const len = parseInt(buf.slice(4, 8).toString('ascii'), 16);
        if (buf.length < 8 + len) return;
        clearTimeout(timer);
        sock.end();
        resolve(buf.slice(8, 8 + len).toString('utf8'));
      } else if (head === 'FAIL') {
        clearTimeout(timer);
        sock.end();
        reject(new Error('FAIL: ' + buf.slice(8).toString('utf8')));
      }
    });
    sock.on('error', (e) => { clearTimeout(timer); reject(e); });
  });
}

function shellQuery(cmd) {
  return new Promise((resolve, reject) => {
    const sock = net.connect(PORT, '127.0.0.1');
    let buf = Buffer.alloc(0);
    let out = Buffer.alloc(0);
    let stage = 0; // 0=transport, 1=shell, 2=stream
    const timer = setTimeout(() => { sock.destroy(); reject(new Error('timeout for: ' + cmd)); }, 180000);
    sock.on('connect', () => sock.write(hex4('host:transport:' + SERIAL)));
    sock.on('data', (chunk) => {
      buf = Buffer.concat([buf, chunk]);
      for (;;) {
        if (stage < 2) {
          if (buf.length < 4) break;
          const head = buf.slice(0, 4).toString('ascii');
          if (head === 'OKAY') {
            buf = buf.slice(4);
            stage++;
            if (stage === 1) sock.write(hex4(cmd));
            continue;
          }
          if (head === 'FAIL') {
            let msg = 'FAIL';
            if (buf.length >= 8) msg = buf.slice(8, 8 + parseInt(buf.slice(4, 8).toString('ascii'), 16)).toString('utf8');
            clearTimeout(timer);
            sock.destroy();
            reject(new Error(msg));
            return;
          }
          break;
        }
        out = Buffer.concat([out, buf]);
        buf = Buffer.alloc(0);
        break;
      }
    });
    sock.on('end', () => { clearTimeout(timer); resolve(out.toString('utf8')); });
    sock.on('error', (e) => { clearTimeout(timer); reject(e); });
  });
}

